589	  const USER_COST_FLOOR = 3.0;  // list: aggregated user prompts
590	  const USER_TOP_N = 20;
591	  const perAssistant = [];
592	  const perUserTurnAll = [];
593	  let maxX = 0;
594	
595	  // Compose a short badge string from evt + rl for display (mirrors template.html).
596	  function evtRlToBadge(evt, rl) {
597	    const parts = (evt || '').split('|').filter(Boolean);
598	    let s = '';
599	    if (parts.indexOf('cost_danger') >= 0) s += '**';
600	    else if (parts.indexOf('cost_warn') >= 0) s += '*';
601	    if (parts.indexOf('ctx_danger') >= 0) s += '##';
602	    else if (parts.indexOf('ctx_warn') >= 0) s += '#';
603	    if (parts.indexOf('heuristic_resume') >= 0) s += '?';
604	    if (rl) {
605	      const m = rl.match(/^limit_hit_(5h|weekly|opus|sonnet|extra|unknown)/);
606	      if (m) {
607	        const map = { '5h':'%5','weekly':'%W','opus':'%O','sonnet':'%S','extra':'%X','unknown':'%%' };
608	        s += map[m[1]] || '%%';
609	      }
610	    }
611	    return s;
612	  }
613	
614	  // Format HH:MM from epoch seconds (local time).
615	  function fmtLocalTime(epochSec) {
616	    if (!epochSec) return '';
617	    const d = new Date(epochSec * 1000);
618	    return String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
619	  }
620	
621	  for (const [sessionId, rows] of allTimelines) {
622	    const sess = sessionMap.get(sessionId);
623	    if (!sess) continue;
624	    const shortSid = sessionId.replace(/^agent-/, '').slice(0, 8);
625	
626	    // For per-assistant tooltips we want the enclosing user prompt's text
627	    // so the user can see "what prompt triggered this expensive call".
628	    // Subagents have no compact.txt → we'll fall back to the row's own data.
629	    const isSubagent = sess.filePath && sess.filePath.includes('/subagents/');
630	    let sortedUsers = [];
631	    let userAlerts = [];
632	    if (!isSubagent) {
633	      userAlerts = readCompactAlerts(sessionId) || [];
634	      sortedUsers = userAlerts.slice().sort((a, b) => a.lineNum - b.lineNum);
635	    }
