638	      if (!sortedUsers.length || rline <= 0) return null;
639	      let lo = 0, hi = sortedUsers.length - 1, found = -1;
640	      while (lo <= hi) {
641	        const mid = (lo + hi) >> 1;
642	        if (sortedUsers[mid].lineNum <= rline) { found = mid; lo = mid + 1; }
643	        else hi = mid - 1;
644	      }
645	      return found >= 0 ? sortedUsers[found] : null;
646	    }
647	
648	    // Per-assistant: every real-turn row, filtered to cost >= ASST_COST_FLOOR
649	    for (const row of rows) {
650	      if (row.cost <= 0 || row.input <= 0) continue;
651	      const ctx = (row.input || 0) + (row.cc || 0) + (row.cr || 0);
652	      if (ctx <= 0) continue;
653	      if (ctx > maxX) maxX = ctx;
654	      if (row.cost < ASST_COST_FLOOR) continue;
655	
656	      const parent = findEnclosingUser(row.line || 0);
657	      perAssistant.push({
658	        x: ctx,
659	        y: Math.round(row.cost * 10000) / 10000,
660	        badge: evtRlToBadge(row.evt, row.rl),
661	        time: parent ? parent.time : fmtLocalTime(row.ts),
662	        sid: shortSid,
663	        text: parent ? (parent.text || '') : '',
664	        input: row.input,
665	        out: row.out,
666	        cc: (row.cc5m || 0) + (row.cc1h || 0),
667	        cr: row.cr
668	      });
669	    }
670	
671	    // Per-user-turn: group rows by enclosing user line, aggregate, filter
672	    if (isSubagent || sortedUsers.length === 0) continue;
673	
674	    const groups = new Map();
675	    for (const u of sortedUsers) {
676	      groups.set(u.lineNum, {
677	        alert: u, firstCtx: null, cost: 0, callCount: 0,
678	        input: 0, out: 0, cc: 0, cr: 0,
679	        firstTs: null, lastTs: null,
680	        evts: new Set(), rl: ''
681	      });
682	    }
683	    for (const row of rows) {
684	      if (row.cost <= 0 || row.input <= 0) continue;
685	      const rline = row.line || 0;
686	      if (rline <= 0) continue;
687	      const parent = findEnclosingUser(rline);
688	      if (!parent) continue;
