708	      const durationSec = g.firstTs && g.lastTs ? Math.max(0, g.lastTs - g.firstTs) : 0;
709	
710	      // Badge rebuild: replace per-row cost tags with USER-TURN aggregate
711	      // thresholds so that a $40 prompt made of 100 small calls still shows **.
712	      // Ctx/heuristic/rate-limit tags from per-row union are preserved.
713	      const aggEvts = new Set(g.evts);
714	      aggEvts.delete('cost_warn');
715	      aggEvts.delete('cost_danger');
716	      if (g.cost >= 10.0) aggEvts.add('cost_danger');
717	      else if (g.cost >= USER_COST_FLOOR) aggEvts.add('cost_warn');
718	
719	      perUserTurnAll.push({
720	        ctx: g.firstCtx,
721	        cost: Math.round(g.cost * 10000) / 10000,
722	        callCount: g.callCount,
723	        durationSec,
