// Build context-vs-cost analysis data:
//   perAssistant — scatter of every API call with cost >= $1 (shows clear slope)
//   perUserTurn  — top-20 list of user prompts with aggregated cost >= $3
//                  (a list is more readable than a scatter for user prompts,
//                   and includes call count which explains why aggregates grow)
//
// Each entry carries marker badge, time, sid, text, token breakdown, callCount.
function buildContextCostScatters(allTimelines, sessionMap) {
  const ASST_COST_FLOOR = 1.0;  // scatter: individual calls
  const USER_COST_FLOOR = 3.0;  // list: aggregated user prompts
  const USER_TOP_N = 20;
  const perAssistant = [];
  const perUserTurnAll = [];
  let maxX = 0;

  // Compose a short badge string from evt + rl for display (mirrors template.html).
  function evtRlToBadge(evt, rl) {
    const parts = (evt || '').split('|').filter(Boolean);
    let s = '';
    if (parts.indexOf('cost_danger') >= 0) s += '**';
    else if (parts.indexOf('cost_warn') >= 0) s += '*';
    if (parts.indexOf('ctx_danger') >= 0) s += '##';
    else if (parts.indexOf('ctx_warn') >= 0) s += '#';
    if (parts.indexOf('heuristic_resume') >= 0) s += '?';
    if (rl) {
      const m = rl.match(/^limit_hit_(5h|weekly|opus|sonnet|extra|unknown)/);
      if (m) {
        const map = { '5h':'%5','weekly':'%W','opus':'%O','sonnet':'%S','extra':'%X','unknown':'%%' };
        s += map[m[1]] || '%%';
      }
    }
    return s;
  }

  // Format HH:MM from epoch seconds (local time).
  function fmtLocalTime(epochSec) {
    if (!epochSec) return '';
    const d = new Date(epochSec * 1000);
    return String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
  }

  for (const [sessionId, rows] of allTimelines) {
    const sess = sessionMap.get(sessionId);
    if (!sess) continue;
    const shortSid = sessionId.replace(/^agent-/, '').slice(0, 8);

    // For per-assistant tooltips we want the enclosing user prompt's text
    // so the user can see "what prompt triggered this expensive call".
    // Subagents have no compact.txt → we'll fall back to the row's own data.
    const isSubagent = sess.filePath && sess.filePath.includes('/subagents/');
    let sortedUsers = [];
    let userAlerts = [];
    if (!isSubagent) {
      userAlerts = readCompactAlerts(sessionId) || [];
      sortedUsers = userAlerts.slice().sort((a, b) => a.lineNum - b.lineNum);
    }

    function findEnclosingUser(rline) {
      if (!sortedUsers.length || rline <= 0) return null;
      let lo = 0, hi = sortedUsers.length - 1, found = -1;
      while (lo <= hi) {
        const mid = (lo + hi) >> 1;
        if (sortedUsers[mid].lineNum <= rline) { found = mid; lo = mid + 1; }
        else hi = mid - 1;
      }
      return found >= 0 ? sortedUsers[found] : null;
    }

    // Per-assistant: every real-turn row, filtered to cost >= ASST_COST_FLOOR
    for (const row of rows) {
      if (row.cost <= 0 || row.input <= 0) continue;
      const ctx = (row.input || 0) + (row.cc || 0) + (row.cr || 0);
      if (ctx <= 0) continue;
      if (ctx > maxX) maxX = ctx;
      if (row.cost < ASST_COST_FLOOR) continue;

      const parent = findEnclosingUser(row.line || 0);
      perAssistant.push({
        x: ctx,
        y: Math.round(row.cost * 10000) / 10000,
        badge: evtRlToBadge(row.evt, row.rl),
        time: parent ? parent.time : fmtLocalTime(row.ts),
        sid: shortSid,
        text: parent ? (parent.text || '') : '',
        input: row.input,
        out: row.out,
        cc: (row.cc5m || 0) + (row.cc1h || 0),
        cr: row.cr
      });
    }

    // Per-user-turn: group rows by enclosing user line, aggregate, filter
    if (isSubagent || sortedUsers.length === 0) continue;

    const groups = new Map();
    for (const u of sortedUsers) {
      groups.set(u.lineNum, {
        alert: u, firstCtx: null, cost: 0, callCount: 0,
        input: 0, out: 0, cc: 0, cr: 0,
        firstTs: null, lastTs: null,
        evts: new Set(), rl: ''
      });
    }
    for (const row of rows) {
      if (row.cost <= 0 || row.input <= 0) continue;
      const rline = row.line || 0;
      if (rline <= 0) continue;
      const parent = findEnclosingUser(rline);
      if (!parent) continue;
      const g = groups.get(parent.lineNum);
      if (g.firstCtx === null) {
        g.firstCtx = (row.input || 0) + (row.cc || 0) + (row.cr || 0);
      }
      g.cost += row.cost;
      g.callCount++;
      g.input += row.input || 0;
      g.out += row.out || 0;
      g.cc += (row.cc5m || 0) + (row.cc1h || 0);
      g.cr += row.cr || 0;
      if (row.ts) {
        if (g.firstTs === null || row.ts < g.firstTs) g.firstTs = row.ts;
        if (g.lastTs === null || row.ts > g.lastTs) g.lastTs = row.ts;
      }
      for (const e of (row.evt || '').split('|')) if (e) g.evts.add(e);
      if (row.rl && !g.rl) g.rl = row.rl;
    }
    for (const g of groups.values()) {
      if (g.firstCtx === null || g.cost < USER_COST_FLOOR) continue;
      const durationSec = g.firstTs && g.lastTs ? Math.max(0, g.lastTs - g.firstTs) : 0;

      // Badge rebuild: replace per-row cost tags with USER-TURN aggregate
      // thresholds so that a $40 prompt made of 100 small calls still shows **.
      // Ctx/heuristic/rate-limit tags from per-row union are preserved.
      const aggEvts = new Set(g.evts);
      aggEvts.delete('cost_warn');
      aggEvts.delete('cost_danger');
      if (g.cost >= 10.0) aggEvts.add('cost_danger');
      else if (g.cost >= USER_COST_FLOOR) aggEvts.add('cost_warn');

      perUserTurnAll.push({
        ctx: g.firstCtx,
        cost: Math.round(g.cost * 10000) / 10000,
        callCount: g.callCount,
        durationSec,
        autonomous: durationSec >= 1800,  // >= 30 minutes
        badge: evtRlToBadge(Array.from(aggEvts).join('|'), g.rl),
        time: g.alert.time,
        sid: shortSid,
        text: g.alert.text || '',
        input: g.input,
        out: g.out,
        cc: g.cc,
        cr: g.cr
      });
    }
  }

  // Binned trend line for the per-assistant scatter.
  function binnedTrend(points) {
    const binCount = 100;
    const binSize = (maxX || 1) / binCount;
    const bins = Array.from({ length: binCount + 1 }, () => ({ sum: 0, count: 0 }));
    for (const p of points) {
      const i = Math.min(binCount, Math.floor(p.x / binSize));
      bins[i].sum += p.y;
      bins[i].count++;
    }
    const trend = [];
    for (let i = 0; i < binCount; i++) {
      if (bins[i].count === 0) continue;
      trend.push({
        x: Math.round((i + 0.5) * binSize),
        y: Math.round((bins[i].sum / bins[i].count) * 10000) / 10000
      });
    }
    return trend;
  }

  // Top N user prompts by total cost
  perUserTurnAll.sort((a, b) => b.cost - a.cost);
  const userTop = perUserTurnAll.slice(0, USER_TOP_N);

  return {
    perAssistant: {
      points: perAssistant,
      trend: binnedTrend(perAssistant),
      totalCount: perAssistant.length,
      costFloor: ASST_COST_FLOOR
    },
    perUserTurn: {
      top: userTop,
      totalCount: perUserTurnAll.length,
      costFloor: USER_COST_FLOOR,
      topN: USER_TOP_N
    },
    maxX: Math.ceil(maxX * 1.1)
  };
}

// ── Build REPORT_DATA ───────────────────────────────────────────

