.chart-wrapper {
  position: relative;
  width: 100%;
}

.donut-wrapper {
  max-width: 280px;
  margin: 0 auto;
}

@media (max-width: 900px) {
  .summary-bar { grid-template-columns: repeat(3, 1fr); }
  .charts-grid { grid-template-columns: 1fr; }
