}

@media (max-width: 600px) {
  .summary-bar { grid-template-columns: 1fr; }
  .breakdown-grid { grid-template-columns: 1fr; }
  .container { padding: 12px; }
  header { flex-direction: column; align-items: flex-start; gap: 12px; }
}

