602	  function evtRlToBadge(evt, rl) {
603	    const parts = (evt || '').split('|').filter(Boolean);
604	    let s = '';
605	    if (parts.indexOf('cost_danger') >= 0) s += '**';
606	    else if (parts.indexOf('cost_warn') >= 0) s += '*';
607	    if (parts.indexOf('ctx_danger') >= 0) s += '##';
608	    else if (parts.indexOf('ctx_warn') >= 0) s += '#';
609	    if (parts.indexOf('heuristic_resume') >= 0) s += '?';
610	    if (rl) {
611	      const m = rl.match(/^limit_hit_(5h|weekly|opus|sonnet|extra|unknown)/);
612	      if (m) {
613	        const map = { '5h':'%5','weekly':'%W','opus':'%O','sonnet':'%S','extra':'%X','unknown':'%%' };
614	        s += map[m[1]] || '%%';
615	      }
616	    }
617	    return s;
618	  }
