643	    function findEnclosingUser(rline) {
644	      if (!sortedUsers.length || rline <= 0) return null;
645	      let lo = 0, hi = sortedUsers.length - 1, found = -1;
646	      while (lo <= hi) {
647	        const mid = (lo + hi) >> 1;
648	        if (sortedUsers[mid].lineNum <= rline) { found = mid; lo = mid + 1; }
649	        else hi = mid - 1;
650	      }
651	      return found >= 0 ? sortedUsers[found] : null;
652	    }
