  const costs = Object.values(dowCostsByWeek[dow]);
  const avg = round2(costs.reduce((s, c) => s + c, 0) / costs.length);
  const max = round2(Math.max(...costs));
  dowStats.push({ dow, label: dowLabels[dow], avg, max });
}

