    const win = cols[9] || prevWin;
    if (cols[1]) prevModel = cols[1];
    if (cols[9]) prevWin = cols[9];
    rows.push({
      ts: Number(cols[0]),
      model,
      input: Number(cols[2]),
      cc: Number(cols[3]),
      cc5m: Number(cols[4]),
