const COST_FLOOR_OTHER = 0.3;
const AUTONOMOUS_DURATION_SEC = 1200;     // user turn wall-clock span >= 20 min
const AUTONOMOUS_MIN_ACTIVE_SEC = 600;    // continuous work time (gaps <= 60s summed) >= 10 min
const AUTONOMOUS_MIN_CALLS_ALT = 30;      // OR >= 30 total calls (bursty but sustained)
const AUTONOMOUS_MIN_CALLS = 5;           // hard floor for any candidate
// Per-assistant scatter is bucketed by dominant cost-contributor token type.
const byInput = [];
const byOutput = [];
const byCacheCreate = [];
const byCacheRead = [];
const autonomousRunsAll = [];
let maxX = 0;

// Compose a short badge string from evt + rl for display (mirrors template.html).
function evtRlToBadge(evt, rl) {
  const parts = (evt || '').split('|').filter(Boolean);
  let s = '';
  if (parts.indexOf('cost_danger') >= 0) s += '**';
  else if (parts.indexOf('cost_warn') >= 0) s += '*';
  if (parts.indexOf('ctx_danger') >= 0) s += '##';
  else if (parts.indexOf('ctx_warn') >= 0) s += '#';
  if (parts.indexOf('heuristic_resume') >= 0) s += '?';
  if (rl) {
    const m = rl.match(/^limit_hit_(5h|weekly|opus|sonnet|extra|unknown)/);
    if (m) {
      const map = { '5h':'%5','weekly':'%W','opus':'%O','sonnet':'%S','extra':'%X','unknown':'%%' };
      s += map[m[1]] || '%%';
    }
  }
  return s;

