const fs = require("fs");
const path = require("path");
const base = require("os").homedir() + "/.claude/cc-token-saver-data";
// Collect ctx (input+cc+cr) distribution for cc5m-dominant vs cc1h-dominant rows
// Use simplified: if cc5m > cc1h and both > 0 → 5m, if cc1h > cc5m → 1h
const ctx5m = [], ctx1h = [];
const cost5m = [], cost1h = [];
function walk(dir) {
  for (const f of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, f.name);
    if (f.isDirectory()) walk(full);
    else if (f.name === "timeline.csv") {
      const lines = fs.readFileSync(full, "utf8").split("\n");
      if (lines.length < 2) continue;
      const h = lines[0].split(",");
      const iIn = h.indexOf("input"), iCc = h.indexOf("cc"), iCr = h.indexOf("cr");
      const i5 = h.indexOf("cc5m"), i1 = h.indexOf("cc1h"), iCost = h.indexOf("cost");
      if ([iIn,iCc,iCr,i5,i1,iCost].some(x=>x<0)) continue;
      for (let j = 1; j < lines.length; j++) {
        const c = lines[j].split(",");
        if (c.length <= iCost) continue;
        const inp = +c[iIn]||0, cc = +c[iCc]||0, cr = +c[iCr]||0;
        const a = +c[i5]||0, b = +c[i1]||0, cost = +c[iCost]||0;
        if (cost < 0.1) continue;  // filter trivial
        const ctx = inp + cc + cr;
        if (a > 0 && b === 0) { ctx5m.push(ctx); cost5m.push(cost); }
        else if (b > 0 && a === 0) { ctx1h.push(ctx); cost1h.push(cost); }
      }
    }
  }
}
walk(base);
function stats(arr) {
  if (arr.length === 0) return "empty";
  arr.sort((a,b)=>a-b);
  const avg = arr.reduce((s,v)=>s+v,0)/arr.length;
  return { n: arr.length, min: arr[0], p25: arr[Math.floor(arr.length*0.25)], median: arr[Math.floor(arr.length*0.5)], p75: arr[Math.floor(arr.length*0.75)], max: arr[arr.length-1], avg: Math.round(avg) };
}
console.log("=== Context (input+cc+cr) distribution ===");
console.log("5m (subtask):", stats(ctx5m));
console.log("1h (main)   :", stats(ctx1h));
console.log("\n=== Cost per call distribution ===");
console.log("5m:", stats(cost5m));
console.log("1h:", stats(cost1h));
'

