function ft(d) { return String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0'); }
function ym(ts) { const d = new Date(ts); return String(d.getFullYear()).slice(2) + String(d.getMonth() + 1).padStart(2, '0'); }
