const ALERT_LINE_RE = /^\[L(\d+) User ((?:\d{2}-\d{2}T)?\d+:\d+(?::\d+)?)\]([^\s]*)\s*(.*)/;

const { execFile } = require('child_process');
const PREPROCESS_PATH = path.join(__dirname, 'preprocess.js');
