582	//   autonomousRuns  — list of user prompts whose assistant execution duration
583	//                     was >= 20 minutes (Ralph-loop-style autonomous runs).
584	//                     No cost filter — all qualifying runs are emitted,
585	//                     sorted by total cost desc for stable display.
586	//
587	// Each entry carries marker badge, time, sid, text, token breakdown, callCount.
588	function buildContextCostScatters(allTimelines, sessionMap) {
589	  // Per-bucket cost floor: cache_create dominates expensive calls so it gets a
590	  // higher floor; the other token types rarely cross $1, so use $0.30 to expose
591	  // their patterns at all. A row is considered only if its cost ≥ the floor of
592	  // its dominant bucket.
593	  const COST_FLOOR_CACHE_CREATE = 1.0;
594	  const COST_FLOOR_OTHER = 0.3;
