//   autonomousRuns  — list of user prompts whose assistant execution duration
//                     was >= 20 minutes (Ralph-loop-style autonomous runs).
//                     No cost filter — all qualifying runs are emitted,
//                     sorted by total cost desc for stable display.
//
// Each entry carries marker badge, time, sid, text, token breakdown, callCount.
function buildContextCostScatters(allTimelines, sessionMap) {
  // Per-bucket cost floor: cache_create dominates expensive calls so it gets a
  // higher floor; the other token types rarely cross $1, so use $0.30 to expose
  // their patterns at all. A row is considered only if its cost ≥ the floor of
  // its dominant bucket.
  const COST_FLOOR_CACHE_CREATE = 1.0;
  const COST_FLOOR_OTHER = 0.3;
  const AUTONOMOUS_DURATION_SEC = 1200;     // user turn wall-clock span >= 20 min
  const AUTONOMOUS_MIN_ACTIVE_SEC = 600;    // continuous work time (gaps <= 60s summed) >= 10 min
  const AUTONOMOUS_MIN_CALLS_ALT = 30;      // OR >= 30 total calls (bursty but sustained)
  const AUTONOMOUS_MIN_CALLS = 5;           // hard floor for any candidate
  // Per-assistant scatter is bucketed by dominant cost-contributor token type.
  // Cache write is split by tier because 5m ($6.25/MTok) and 1h ($10/MTok) have
  // different slopes AND different typical x-ranges (subtasks stay small, main
  // sessions grow large), which would otherwise collapse into one misleading line.
  const byInput = [];
  const byOutput = [];
  const byCacheCreate5m = [];
  const byCacheCreate1h = [];
  const byCacheRead = [];
  const autonomousRunsAll = [];
  let maxX = 0;

  // Compose a short badge string from evt + rl for display (mirrors template.html).
  function evtRlToBadge(evt, rl) {
    const parts = (evt || '').split('|').filter(Boolean);
    let s = '';
    if (parts.indexOf('cost_danger') >= 0) s += '**';
    else if (parts.indexOf('cost_warn') >= 0) s += '*';
    if (parts.indexOf('ctx_danger') >= 0) s += '##';
    else if (parts.indexOf('ctx_warn') >= 0) s += '#';
    if (parts.indexOf('heuristic_resume') >= 0) s += '?';
    if (rl) {
      const m = rl.match(/^limit_hit_(5h|weekly|opus|sonnet|extra|unknown)/);
      if (m) {
        const map = { '5h':'%5','weekly':'%W','opus':'%O','sonnet':'%S','extra':'%X','unknown':'%%' };
        s += map[m[1]] || '%%';
      }
    }
    return s;
  }

  // Format HH:MM from epoch seconds (local time).
  function fmtLocalTime(epochSec) {
    if (!epochSec) return '';
    const d = new Date(epochSec * 1000);
    return String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
  }

  for (const [sessionId, rows] of allTimelines) {
    const sess = sessionMap.get(sessionId);
    if (!sess) continue;
    const shortSid = sessionId.replace(/^agent-/, '').slice(0, 8);

    // For per-assistant tooltips we want the enclosing user prompt's text
    // so the user can see "what prompt triggered this expensive call".
    // Subagents have no compact.txt → we'll fall back to the row's own data.
    const isSubagent = sess.filePath && sess.filePath.includes('/subagents/');
    let sortedUsers = [];
    let userAlerts = [];
    if (!isSubagent) {
      userAlerts = readCompactAlerts(sessionId) || [];
      sortedUsers = userAlerts.slice().sort((a, b) => a.lineNum - b.lineNum);
    }

    function findEnclosingUser(rline) {
      if (!sortedUsers.length || rline <= 0) return null;
      let lo = 0, hi = sortedUsers.length - 1, found = -1;
      while (lo <= hi) {
        const mid = (lo + hi) >> 1;
        if (sortedUsers[mid].lineNum <= rline) { found = mid; lo = mid + 1; }
        else hi = mid - 1;
      }
      return found >= 0 ? sortedUsers[found] : null;
    }

    // Per-assistant: every real-turn row, bucketed by dominant token type with
    // a per-bucket cost floor (cache_create $1+, others $0.30+).
    for (const row of rows) {
      if (row.cost <= 0 || row.input <= 0) continue;
      const ctx = (row.input || 0) + (row.cc || 0) + (row.cr || 0);
      if (ctx <= 0) continue;
      if (ctx > maxX) maxX = ctx;

      // Compute cost breakdown per token type using model pricing. Cache write
      // is split by tier — 5m (subtask) and 1h (main) have different prices AND
      // different typical context distributions, so they become separate buckets.
      const rates = getRates(row.model);
      const inputCost = (row.input || 0) * rates.input / 1e6;
      const outputCost = (row.out || 0) * rates.output / 1e6;
      const cc5mCost = (row.cc5m || 0) * rates.cacheCreate5m / 1e6;
      const cc1hCost = (row.cc1h || 0) * rates.cacheCreate1h / 1e6;
      const crReadCost = (row.cr || 0) * rates.cacheRead / 1e6;

      // Pick dominant across 5 possible categories.
      let dom = 'input';
      let domCost = inputCost;
      if (outputCost > domCost) { dom = 'output'; domCost = outputCost; }
      if (cc5mCost > domCost) { dom = 'cacheCreate5m'; domCost = cc5mCost; }
      if (cc1hCost > domCost) { dom = 'cacheCreate1h'; domCost = cc1hCost; }
      if (crReadCost > domCost) { dom = 'cacheRead'; domCost = crReadCost; }

      // Apply per-bucket floor against TOTAL row cost.
      const isCacheCreate = (dom === 'cacheCreate5m' || dom === 'cacheCreate1h');
      const floor = isCacheCreate ? COST_FLOOR_CACHE_CREATE : COST_FLOOR_OTHER;
      if (row.cost < floor) continue;

      const parent = findEnclosingUser(row.line || 0);
      const point = {
        x: ctx,
        y: Math.round(row.cost * 10000) / 10000,
        badge: evtRlToBadge(row.evt, row.rl),
        time: parent ? parent.time : fmtLocalTime(row.ts),
        sid: shortSid,
        text: parent ? (parent.text || '') : '',
        input: row.input,
        out: row.out,
        cc: (row.cc5m || 0) + (row.cc1h || 0),
        cr: row.cr
      };
      if (dom === 'input') byInput.push(point);
      else if (dom === 'output') byOutput.push(point);
      else if (dom === 'cacheCreate5m') byCacheCreate5m.push(point);
      else if (dom === 'cacheCreate1h') byCacheCreate1h.push(point);
      else byCacheRead.push(point);
    }

    // Per-user-turn: group rows by enclosing user line, aggregate, filter
    if (isSubagent || sortedUsers.length === 0) continue;

    const groups = new Map();
    for (const u of sortedUsers) {
      groups.set(u.lineNum, {
        alert: u, firstCtx: null, cost: 0, callCount: 0,
        input: 0, out: 0, cc: 0, cr: 0,
        firstTs: null, lastTs: null,
        tsList: [],
        evts: new Set(), rl: ''
      });
    }
    for (const row of rows) {
      if (row.cost <= 0 || row.input <= 0) continue;
      const rline = row.line || 0;
      if (rline <= 0) continue;
      const parent = findEnclosingUser(rline);
      if (!parent) continue;
      const g = groups.get(parent.lineNum);
      if (g.firstCtx === null) {
        g.firstCtx = (row.input || 0) + (row.cc || 0) + (row.cr || 0);
      }
      g.cost += row.cost;
      g.callCount++;
      g.input += row.input || 0;
      g.out += row.out || 0;
      g.cc += (row.cc5m || 0) + (row.cc1h || 0);
      g.cr += row.cr || 0;
      if (row.ts) {
        if (g.firstTs === null || row.ts < g.firstTs) g.firstTs = row.ts;
        if (g.lastTs === null || row.ts > g.lastTs) g.lastTs = row.ts;
        g.tsList.push(row.ts);
      }
      for (const e of (row.evt || '').split('|')) if (e) g.evts.add(e);
      if (row.rl && !g.rl) g.rl = row.rl;
    }
    for (const g of groups.values()) {
      if (g.firstCtx === null) continue;
      const durationSec = g.firstTs && g.lastTs ? Math.max(0, g.lastTs - g.firstTs) : 0;
      if (durationSec < AUTONOMOUS_DURATION_SEC) continue;

      // Sort timestamps and compute max idle gap + active-time sum.
      // True autonomous runs have near-continuous API calls. False positives
      // (interrupted/resumed turns) show long gaps where the user was idle.
      g.tsList.sort((a, b) => a - b);
      let gapMaxSec = 0;
      let activeSec = 0;
      for (let i = 1; i < g.tsList.length; i++) {
        const gap = g.tsList[i] - g.tsList[i - 1];
        if (gap > gapMaxSec) gapMaxSec = gap;
        if (gap <= 60) activeSec += gap;
      }
      // Filter false positives: max idle gap must be small and call count sane.
      // Multi-signal filter: per-user-turn grouping already guarantees "no user
      // intervention", so gaps inside a group are SYSTEM (rate-limit/tool), not
      // idle user time. Reject walkaways (few calls + little active work) while
      // keeping rate-limit-resumed runs where active work time survives the pause.
      if (g.callCount < AUTONOMOUS_MIN_CALLS) continue;
      const isSustainedActive = activeSec >= AUTONOMOUS_MIN_ACTIVE_SEC;
      const isBursty = g.callCount >= AUTONOMOUS_MIN_CALLS_ALT;
      if (!isSustainedActive && !isBursty) continue;

      // Badge rebuild: replace per-row cost tags with USER-TURN aggregate
      // thresholds so that a $40 prompt made of 100 small calls still shows **.
      // Ctx/heuristic/rate-limit tags from per-row union are preserved.
      const aggEvts = new Set(g.evts);
      aggEvts.delete('cost_warn');
      aggEvts.delete('cost_danger');
      if (g.cost >= 10.0) aggEvts.add('cost_danger');
      else if (g.cost >= 3.0) aggEvts.add('cost_warn');

      autonomousRunsAll.push({
        ctx: g.firstCtx,
        cost: Math.round(g.cost * 10000) / 10000,
        callCount: g.callCount,
        durationSec,
        gapMaxSec,
        activeSec,
        autonomous: true,  // by definition every entry here is autonomous
        badge: evtRlToBadge(Array.from(aggEvts).join('|'), g.rl),
        time: g.alert.time,
        sid: shortSid,
        text: g.alert.text || '',
        input: g.input,
        out: g.out,
        cc: g.cc,
        cr: g.cr
      });
    }
  }

  // Simple least-squares linear regression over a point list.
  // Returns { slope, intercept, x0, x1 } for frontend to plot as a 2-point line.
  function linearTrend(points) {
    if (!points || points.length < 2) return null;
    let n = 0, sx = 0, sy = 0, sxx = 0, sxy = 0;
    let x0 = Infinity, x1 = -Infinity;
    for (const p of points) {
      n++; sx += p.x; sy += p.y; sxx += p.x * p.x; sxy += p.x * p.y;
      if (p.x < x0) x0 = p.x;
      if (p.x > x1) x1 = p.x;
    }
    const denom = n * sxx - sx * sx;
    if (denom === 0) return null;
    const slope = (n * sxy - sx * sy) / denom;
    const intercept = (sy - slope * sx) / n;
    return { slope, intercept, x0, x1 };
  }

  function bucketOut(points, costFloor) {
    return {
      points,
      trend: linearTrend(points),
      totalCount: points.length,
      costFloor
    };

