    const cc1hCost = (row.cc1h || 0) * rates.cacheCreate1h / 1e6;
    const crReadCost = (row.cr || 0) * rates.cacheRead / 1e6;

    // Pick dominant across 5 possible categories.
    let dom = 'input';
    let domCost = inputCost;
    if (outputCost > domCost) { dom = 'output'; domCost = outputCost; }
    if (cc5mCost > domCost) { dom = 'cacheCreate5m'; domCost = cc5mCost; }
    if (cc1hCost > domCost) { dom = 'cacheCreate1h'; domCost = cc1hCost; }
    if (crReadCost > domCost) { dom = 'cacheRead'; domCost = crReadCost; }

    // Apply per-bucket floor against TOTAL row cost.
    const isCacheCreate = (dom === 'cacheCreate5m' || dom === 'cacheCreate1h');
    const floor = isCacheCreate ? COST_FLOOR_CACHE_CREATE : COST_FLOOR_OTHER;
    if (row.cost < floor) continue;

    const parent = findEnclosingUser(row.line || 0);
    const point = {
      x: ctx,
      y: Math.round(row.cost * 10000) / 10000,
      badge: evtRlToBadge(row.evt, row.rl),
      time: parent ? parent.time : fmtLocalTime(row.ts),
      sid: shortSid,
      text: parent ? (parent.text || '') : '',
      input: row.input,
      out: row.out,
      cc: (row.cc5m || 0) + (row.cc1h || 0),
      cr: row.cr
    };
    if (dom === 'input') byInput.push(point);
    else if (dom === 'output') byOutput.push(point);
    else if (dom === 'cacheCreate5m') byCacheCreate5m.push(point);
    else if (dom === 'cacheCreate1h') byCacheCreate1h.push(point);
    else byCacheRead.push(point);
  }

  // Per-user-turn: group rows by enclosing user line, aggregate, filter
  if (isSubagent || sortedUsers.length === 0) continue;

  const groups = new Map();
  for (const u of sortedUsers) {
    groups.set(u.lineNum, {
      alert: u, firstCtx: null, cost: 0, callCount: 0,
      input: 0, out: 0, cc: 0, cr: 0,
      firstTs: null, lastTs: null,
      tsList: [],
      evts: new Set(), rl: ''
    });
  }
  for (const row of rows) {
    if (row.cost <= 0 || row.input <= 0) continue;
    const rline = row.line || 0;
    if (rline <= 0) continue;
    const parent = findEnclosingUser(rline);
    if (!parent) continue;
    const g = groups.get(parent.lineNum);
    if (g.firstCtx === null) {
      g.firstCtx = (row.input || 0) + (row.cc || 0) + (row.cr || 0);
    }
    g.cost += row.cost;
    g.callCount++;
    g.input += row.input || 0;
    g.out += row.out || 0;
    g.cc += (row.cc5m || 0) + (row.cc1h || 0);
    g.cr += row.cr || 0;
    if (row.ts) {
      if (g.firstTs === null || row.ts < g.firstTs) g.firstTs = row.ts;
      if (g.lastTs === null || row.ts > g.lastTs) g.lastTs = row.ts;
      g.tsList.push(row.ts);
    }
    for (const e of (row.evt || '').split('|')) if (e) g.evts.add(e);
    if (row.rl && !g.rl) g.rl = row.rl;
  }
  for (const g of groups.values()) {
    if (g.firstCtx === null) continue;
    const durationSec = g.firstTs && g.lastTs ? Math.max(0, g.lastTs - g.firstTs) : 0;
    if (durationSec < AUTONOMOUS_DURATION_SEC) continue;

    // Sort timestamps and compute max idle gap + active-time sum.
    // True autonomous runs have near-continuous API calls. False positives
    // (interrupted/resumed turns) show long gaps where the user was idle.
    g.tsList.sort((a, b) => a - b);
    let gapMaxSec = 0;
    let activeSec = 0;
    for (let i = 1; i < g.tsList.length; i++) {
      const gap = g.tsList[i] - g.tsList[i - 1];
      if (gap > gapMaxSec) gapMaxSec = gap;
      if (gap <= 60) activeSec += gap;
    }
    // Filter false positives: max idle gap must be small and call count sane.
    // Multi-signal filter: per-user-turn grouping already guarantees "no user
    // intervention", so gaps inside a group are SYSTEM (rate-limit/tool), not
    // idle user time. Reject walkaways (few calls + little active work) while
    // keeping rate-limit-resumed runs where active work time survives the pause.
    if (g.callCount < AUTONOMOUS_MIN_CALLS) continue;
    const isSustainedActive = activeSec >= AUTONOMOUS_MIN_ACTIVE_SEC;
    const isBursty = g.callCount >= AUTONOMOUS_MIN_CALLS_ALT;
    if (!isSustainedActive && !isBursty) continue;

    // Badge rebuild: replace per-row cost tags with USER-TURN aggregate
    // thresholds so that a $40 prompt made of 100 small calls still shows **.
    // Ctx/heuristic/rate-limit tags from per-row union are preserved.
    const aggEvts = new Set(g.evts);
    aggEvts.delete('cost_warn');
    aggEvts.delete('cost_danger');
    if (g.cost >= 10.0) aggEvts.add('cost_danger');
    else if (g.cost >= 3.0) aggEvts.add('cost_warn');

    autonomousRunsAll.push({
      ctx: g.firstCtx,
      cost: Math.round(g.cost * 10000) / 10000,
      callCount: g.callCount,
      durationSec,
      gapMaxSec,
      activeSec,
      autonomous: true,  // by definition every entry here is autonomous
      badge: evtRlToBadge(Array.from(aggEvts).join('|'), g.rl),
      time: g.alert.time,
      sid: shortSid,
      text: g.alert.text || '',
      input: g.input,
      out: g.out,
      cc: g.cc,
      cr: g.cr
    });
  }
}

