function fmtDuration(sec) {
  if (!sec || sec <= 0) return '';
  var h = Math.floor(sec / 3600);
  var m = Math.floor((sec % 3600) / 60);
  var s = Math.floor(sec % 60);
  if (h > 0) return h + 'h' + (m > 0 ? m + 'm' : '');
  if (m > 0) return m + 'm' + (s > 0 ? s + 's' : '');
  return s + 's';
}

function renderAutonomousRuns(data) {
  var container = document.getElementById('autonomousRunsList');
  if (!container) return;
  if (!data || !data.list || data.list.length === 0) {
    var wrap = document.getElementById('autonomousRunsContainer');
    if (wrap) wrap.style.display = 'none';
    return;
  }
  // Clear container via DOM (no innerHTML)
  while (container.firstChild) container.removeChild(container.firstChild);
  var list = data.list;
  for (var i = 0; i < list.length; i++) {
    var t = list[i];
    var row = createEl('div', { style: { padding: '6px 8px', borderBottom: '1px solid var(--border)', lineHeight: '1.5' } });

    // Line 1: rank · badge · time · sid · duration · calls
    var header = createEl('div', { style: { display: 'flex', gap: '8px', alignItems: 'baseline', flexWrap: 'wrap' } });
    header.appendChild(createEl('span', { style: { color: 'var(--text-muted)', minWidth: '24px' }, textContent: '#' + (i + 1) }));
    if (t.badge) {
      header.appendChild(createEl('span', { style: { color: '#ff7b72', fontWeight: 'bold' }, textContent: '[' + t.badge + ']' }));
    }
    header.appendChild(createEl('span', { style: { color: 'var(--text-secondary)' }, textContent: t.time || '' }));
    if (t.sid) {
      header.appendChild(createEl('span', { style: { color: 'var(--accent-blue)', fontSize: '11px' }, textContent: t.sid }));
    }
    // Duration gets prominent placement with ⏱ indicator
    var durText = '⏱ ' + (t.durationSec > 0 ? fmtDuration(t.durationSec) : '-');
    header.appendChild(createEl('span', { style: { color: '#ff7b72', fontSize: '11px', fontWeight: 'bold' }, textContent: durText }));
    header.appendChild(createEl('span', { style: { color: 'var(--text-muted)', fontSize: '11px' }, textContent: t.callCount + ' calls' }));
    row.appendChild(header);

    // Line 2: text
    if (t.text) {
      var txt = String(t.text);
      if (txt.length > 140) txt = txt.slice(0, 140) + '…';
      row.appendChild(createEl('div', { style: { color: 'var(--text-primary)', margin: '3px 0 3px 32px', fontStyle: 'italic' }, textContent: '"' + txt + '"' }));
    }

    // Line 3: stats
    var parts = ['$' + t.cost.toFixed(2)];
    if (t.input) parts.push('Input ' + fmtTokens(t.input));
    if (t.out) parts.push('Output ' + fmtTokens(t.out));
    if (t.cc) parts.push('Cache ' + fmtTokens(t.cc));
    if (t.cr) parts.push('Read ' + fmtTokens(t.cr));
    row.appendChild(createEl('div', { style: { color: 'var(--text-muted)', margin: '0 0 0 32px', fontSize: '11px' }, textContent: parts.join(' · ') }));

    container.appendChild(row);
  }
}

function renderContextCostCharts() {
  var ccs = REPORT_DATA.contextCostScatter;
  if (!ccs) return;
  renderAutonomousRuns(ccs.autonomousRuns);
  var pa = ccs.perAssistant || {};
  var yLabel = 'Cost per API call ($)';
  var anyPoints = 0;
  var buckets = [
    ['ctxCostInputChart',          'ctxCostInputWrap',          pa.byInput],
    ['ctxCostOutputChart',         'ctxCostOutputWrap',         pa.byOutput],
    ['ctxCostCacheReadChart',      'ctxCostCacheReadWrap',      pa.byCacheRead],
    ['ctxCostCacheCreate5mChart',  'ctxCostCacheCreate5mWrap',  pa.byCacheCreate5m],
    ['ctxCostCacheCreate1hChart',  'ctxCostCacheCreate1hWrap',  pa.byCacheCreate1h]
  ];
  for (var i = 0; i < buckets.length; i++) {
    var b = buckets[i];
    var bucket = b[2];
    if (bucket && bucket.points && bucket.points.length > 0) anyPoints++;
    // Each bucket carries its own costFloor (cache_create=$1, others=$0.30).
    var bucketFloor = (bucket && bucket.costFloor != null) ? bucket.costFloor : 1.0;
    renderContextCostChart(b[0], b[1], bucket, yLabel, bucketFloor);
  }
  if (anyPoints === 0) {
    var cont = document.getElementById('ctxCostAsstContainer');
    if (cont) cont.style.display = 'none';
  }
}

