    var cwCost = (t.cc1h || 0) * rCW1h + (t.cc5m || 0) * rCW5m;
    var tCacheWrite = (I18N.alert.costTypeCacheWrite || 'cache write');
    var tCacheRead = (I18N.alert.costTypeCacheRead || 'cache read');
    var tOutput = (I18N.alert.costTypeOutput || 'output');
    var tInput = (I18N.alert.costTypeInput || 'input');
    var costs = [
      { name: 'cache write', val: cwCost, tokens: cwTokens, type: tCacheWrite, label: tCacheWrite + ' ' + fmtTokens(cwTokens) },
      { name: 'cache read', val: (t.cr || 0) * rCR, tokens: t.cr || 0, type: tCacheRead, label: tCacheRead + ' ' + fmtTokens(t.cr||0) },
      { name: 'output', val: (t.out || 0) * rOut, tokens: t.out || 0, type: tOutput, label: tOutput + ' ' + fmtTokens(t.out||0) },
      { name: 'input', val: (t.input || 0) * rIn, tokens: t.input || 0, type: tInput, label: tInput + ' ' + fmtTokens(t.input||0) }
    ];
    costs.sort(function(a, b) { return b.val - a.val; });
    var top = costs[0];
    var icon = typ === 'cost-danger' ? '\uD83D\uDD34' : '\u26A0\uFE0F';
    if (top.name === 'cache write' && top.val > 0) {
      // Common prefix for all cache write cases
      var cwPrefix = i18nT(I18N.alert.cacheWritePrefix, { icon: icon, tokens: fmtTokens(top.tokens) });
      // Determine reason based on session markers
      var hasCompactManual = false, hasCompactAuto = false, hasContinue = false, hasStartup = false, hasClear = false;
      var hasReload = false, hasModel = false, hasResumeHeuristic = false;
      for (var si = 0; si < types.length; si++) {
        var st = types[si];
        if (st === 'compact-manual') hasCompactManual = true;
        else if (st === 'compact-auto') hasCompactAuto = true;
        else if (st === 'continue-1' || st === 'continue-n') hasContinue = true;
        else if (st === 'startup') hasStartup = true;
        else if (st === 'clear') hasClear = true;
        else if (st === 'reload-plugins') hasReload = true;
        else if (st === 'model-change') hasModel = true;
        else if (st === 'resume-heuristic') hasResumeHeuristic = true;
      }
      if (hasCompactManual) {
        diagMsg += cwPrefix + I18N.alert.compactManualReason + continueSkillTip;
      } else if (hasCompactAuto) {
        diagMsg += cwPrefix + I18N.alert.compactAutoReason + continueSkillTip;
      } else if (hasClear || hasStartup) {
        var startupTip = top.tokens >= 30000 ? I18N.alert.pluginOverload : '';
        var reason = hasClear ? I18N.alert.clearReasonClear : I18N.alert.clearReasonStartup;
        diagMsg += cwPrefix + i18nT(I18N.alert.clearReason, { reason: reason, cost: t.cost.toFixed(2) }) + startupTip + '\n';
      } else if (hasContinue) {
        diagMsg += cwPrefix + '/continue ($' + t.cost.toFixed(2) + ')\n';
      } else if (hasReload) {
        diagMsg += cwPrefix + i18nT(I18N.alert.reloadReason, { cost: t.cost.toFixed(2) }) + '\n';
      } else if (hasModel) {
        diagMsg += cwPrefix + i18nT(I18N.alert.modelReason, { cost: t.cost.toFixed(2) }) + '\n';
      } else if (hasResumeHeuristic) {
        diagMsg += cwPrefix + I18N.alert.resumeHeuristicReason + '\n';
      } else {
        diagMsg += cwPrefix + I18N.alert.cacheExpiredReason + continueSkillTip;
      }
    } else if (top.name === 'cache read') {
      // Cache read dominated — ctx warning (*#) usually covers this, so skip when ctx marker present.
      // But when only cost marker (*) exists without ctx (#), show the reason.
      var hasCtx = types.indexOf('ctx-warn') >= 0 || types.indexOf('ctx-danger') >= 0;
      if (!hasCtx) {
        var hasResumeH = types.indexOf('resume-heuristic') >= 0;
        if (hasResumeH) {
          diagMsg += i18nT(I18N.alert.costTopLabel, { icon: icon, type: top.type, tokens: fmtTokens(top.tokens), cost: t.cost.toFixed(2) }) + '\n';
          diagMsg += icon + ' ' + I18N.alert.resumeHeuristicReason + '\n';
        } else {
          diagMsg += i18nT(I18N.alert.costTopLabel, { icon: icon, type: top.type, tokens: fmtTokens(top.tokens), cost: t.cost.toFixed(2) }) + '\n';
        }
      }
    } else if (top.name === 'output') {
      diagMsg += i18nT(I18N.alert.costOutputReason, { icon: icon, tokens: fmtTokens(top.tokens), cost: t.cost.toFixed(2) }) + '\n';
