.cost-filter-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 8px;
  font-size: 12px;
  color: var(--text-secondary);
  flex-wrap: wrap;
}
.cost-filter-row label { white-space: nowrap; }
.cost-filter-row input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  width: 180px;
  height: 4px;
  background: var(--border);
  border-radius: 2px;
  outline: none;
}
.cost-filter-row input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--accent);
  cursor: pointer;
  border: 0;
}
.cost-filter-row input[type="range"]::-moz-range-thumb {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--accent);
  cursor: pointer;
  border: 0;
}
.cost-filter-row .cost-filter-value {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  min-width: 48px;
  color: var(--text-primary);
}
.cost-filter-row .cost-filter-count {
  color: var(--text-muted);
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 4px;

