var effNote = document.querySelector('#efficiencyChart').closest('.chart-container').querySelector('div[style*="font-size:11px"]');
if (effNote) effNote.textContent = I18N.chart.effNote;

// Calendar section title (use specific class — generic .section-title would
// grab the first matching element, which is now the Long Runs section above)
var calTitle = document.querySelector('.calendar-section-title');
if (calTitle) {
  var calToggle = document.getElementById('calendarClickMode');
  var titleText = '\uD83D\uDCC5 ' + I18N.calendar.title;
  while (calTitle.firstChild) calTitle.removeChild(calTitle.firstChild);
  calTitle.appendChild(document.createTextNode(titleText));
  if (calToggle) calTitle.appendChild(calToggle);
}

// Calendar toggle buttons
var windowBtn = document.querySelector('[data-mode="window"]');
var blockBtn = document.querySelector('[data-mode="block"]');
if (windowBtn) windowBtn.textContent = I18N.calendar.fiveHourWindow;
if (blockBtn) blockBtn.textContent = I18N.calendar.oneHourBlock;

