function renderAlertItems(alerts, container, sessionType) {
  container.textContent = '';
  if (alerts.length === 0) {
    container.appendChild(createEl('div', { className: 'alert-empty', textContent: I18N.calendar.noData }));
    return;
  }
  for (var i = 0; i < alerts.length; i++) {
    var a = alerts[i];
    if (a.isInfoOnly) continue;  // info-only alerts kept in data but not rendered
    // Skip alerts with /continue skill (^ or ^^) — /continue saves tokens vs compact, not a cost event
    var aTypes = (a.alertType || '').split('+');
    var hasContinueMarker = aTypes.indexOf('continue-1') >= 0 || aTypes.indexOf('continue-n') >= 0;
    if (hasContinueMarker) continue;
    var item = createEl('div', { className: 'alert-item' });

    var header = createEl('div', { className: 'alert-header' });
    // Show markers but: strip skipped types (continue ^/^^, info-only session markers)
    // and remove {extra info} suffixes
    var rawMarkers = a.markers || '';
    // Remove {…} suffixes (e.g. {1am@Asia/Seoul}, {restart})
    var cleanMarkers = rawMarkers.replace(/\{[^}]*\}/g, '');
    // Remove continue markers (^ ^^)
    cleanMarkers = cleanMarkers.replace(/\^+/g, '');
    // Remove session-only markers that are info-only (@, @@, +, ++, ~, !, ?)
    cleanMarkers = cleanMarkers.replace(/@@|@|\+\+|\+|~|!|\?/g, '');
    cleanMarkers = cleanMarkers.trim();
    if (cleanMarkers) {
      var markerClass = getAlertMarkerClass(a.alertType);
      header.appendChild(createEl('span', { className: 'alert-markers ' + markerClass, textContent: '[' + cleanMarkers + ']' }));
    }
    header.appendChild(createEl('span', { className: 'alert-time', textContent: a.time }));
    if (a.sessionId) {
      header.appendChild(createEl('span', { style: { color: 'var(--accent-blue)', fontFamily: 'monospace', fontSize: '11px' }, textContent: a.sessionId.slice(0, 8) }));
    }
    item.appendChild(header);

    if (a.text) {
      item.appendChild(createEl('div', { className: 'alert-text', textContent: '"' + a.text + '"' }));
    }

    // Token/cost summary line
    if (a.tokens) {
      var t = a.tokens;
      var parts = [];
      parts.push('$' + (t.cost || 0).toFixed(2));
      if (t.input) parts.push('Input ' + fmtTokens(t.input));
      if (t.out) parts.push('Output ' + fmtTokens(t.out));
      if ((t.cc1h || 0) + (t.cc5m || 0) > 0) parts.push('Cache ' + fmtTokens((t.cc1h || 0) + (t.cc5m || 0)));
      if (t.cr) parts.push('Read ' + fmtTokens(t.cr));
      item.appendChild(createEl('div', { className: 'session-stats', textContent: parts.join(' · ') }));
    }

    // Diagnostic message based on alert type
    var diagMsg = '';
    var continueSkillTip = ' ' + I18N.alert.continueSkillTip + '\n';

