const fs = require("fs");
const h = fs.readFileSync("/var/folders/k9/cgrhlf4s5mq1glwbr6__f__c0000gn/T/cc-usage-report-1775826733.html", "utf8");
const m = h.match(/REPORT_DATA = (\{[\s\S]*?\});\n\/\*<!-- REPORT_DATA_END/);
const d = JSON.parse(m[1]);
// Find first window with alertMessages
for (const w of d.windows) {
  if (!w.alertMessages || w.alertMessages.length === 0) continue;
  const withTurnCount = w.alertMessages.filter(a => a.turnCount > 0);
  if (withTurnCount.length === 0) continue;
  console.log(`Window ${w.date} ${w.start}~${w.end}: ${withTurnCount.length} alerts with turnCount`);
  console.log("Sample:");
  withTurnCount.slice(0,3).forEach(a => {
    console.log(`  time=${a.time} turnCount=${a.turnCount} cost=$${a.tokens?.cost?.toFixed(2) || "?"}`);
  });
  break;
}
'

