const fs = require("fs");
const path = require("path");
const os = require("os");
const base = path.join(os.homedir(), ".claude/cc-token-saver-data");

// Quick scan: find user turns with turnCount >= 25 across all sessions
let totalRows = 0, totalTurns = 0, turnsGte25 = 0, turnsGte50 = 0, turnsGte100 = 0;
const topTurns = []; // [{sid, turnCount, cost, proj}]

function scanProject(projDir) {
  for (const entry of fs.readdirSync(projDir, { withFileTypes: true })) {
    if (!entry.isDirectory()) continue;
    const sessDir = path.join(projDir, entry.name);
    const tl = path.join(sessDir, "timeline.csv");
    if (!fs.existsSync(tl)) continue;
    const lines = fs.readFileSync(tl, "utf8").split("\n");
    if (lines.length < 2) continue;
    const header = lines[0].split(",");
    const iLine = header.indexOf("line"), iCost = header.indexOf("cost"), iInput = header.indexOf("input");
    if (iLine < 0) continue;

    // Also need compact.txt to group by user turn boundaries
    const compact = path.join(sessDir, "compact.txt");
    let userLines = [];
    if (fs.existsSync(compact)) {
      const c = fs.readFileSync(compact, "utf8");
      const re = /\[L(\d+) User/g;
      let m;
      while ((m = re.exec(c)) !== null) userLines.push(Number(m[1]));
      userLines.sort((a,b)=>a-b);
    }
    if (userLines.length === 0) continue;

    // Group rows by enclosing user line
    const groups = new Map();
    for (const u of userLines) groups.set(u, { count: 0, cost: 0 });
    for (let j = 1; j < lines.length; j++) {
      const c = lines[j].split(",");
      if (c.length <= iCost) continue;
      const rline = +c[iLine] || 0;
      const rcost = +c[iCost] || 0;
      const rinput = +c[iInput] || 0;
      if (rline <= 0 || (rcost <= 0 && rinput <= 0)) continue;
      totalRows++;
      // Binary search for enclosing user line
      let lo=0, hi=userLines.length-1, found=-1;
      while (lo<=hi) { const mid=(lo+hi)>>1; if (userLines[mid]<=rline){found=mid;lo=mid+1;} else hi=mid-1; }
      if (found<0) continue;
      const g = groups.get(userLines[found]);
      g.count++;
      g.cost += rcost;
    }
    for (const [lineNum, g] of groups) {
      if (g.count === 0) continue;
      totalTurns++;
      if (g.count >= 25) turnsGte25++;
      if (g.count >= 50) turnsGte50++;
      if (g.count >= 100) turnsGte100++;
      if (g.count >= 25) {
        topTurns.push({ sid: entry.name.slice(0,8), turnCount: g.count, cost: g.cost, proj: path.basename(projDir), lineNum });
      }
    }
  }
}

for (const proj of fs.readdirSync(base)) {
  const pdir = path.join(base, proj);
  if (!fs.statSync(pdir).isDirectory()) continue;
  try { scanProject(pdir); } catch(e){}
}

console.log(`Total rows: ${totalRows.toLocaleString()}`);
console.log(`Total user turns: ${totalTurns.toLocaleString()}`);
console.log(`Turns with turnCount >= 25: ${turnsGte25} (${(100*turnsGte25/totalTurns).toFixed(2)}%)`);
console.log(`Turns with turnCount >= 50: ${turnsGte50}`);
console.log(`Turns with turnCount >= 100: ${turnsGte100}`);

topTurns.sort((a,b)=>b.turnCount-a.turnCount);
console.log("\nTop 20 by turnCount:");
for (const t of topTurns.slice(0,20)) {
  console.log(`  ${t.turnCount} calls  $${t.cost.toFixed(2).padStart(7)}  sid=${t.sid}  proj=${t.proj.slice(-20)}  L${t.lineNum}`);
}
EOF

