const fs = require("fs");
const p = "/Users/taehyoungkim/.claude/projects/-Users-taehyoungkim-jobda/50cd6f63-534a-4c15-a940-d37dac99f819.jsonl";
const lines = fs.readFileSync(p, "utf8").split("\n");

// Extract the auto-compact summary at L2942
let summary = "";
try {
  const obj = JSON.parse(lines[2941]);
  const c = obj.message && obj.message.content;
  if (typeof c === "string") summary = c;
  else if (Array.isArray(c)) summary = c.map(b => b.text||"").join("");
} catch(e){}

// Extract file paths mentioned in the summary
const pathRegex = /(?:\/[a-zA-Z0-9._-]+){2,}/g;
const summaryPaths = new Set();
for (const m of summary.match(pathRegex) || []) {
  if (m.endsWith(".ts") || m.endsWith(".tsx") || m.endsWith(".js") || m.endsWith(".jsx") ||
      m.endsWith(".md") || m.endsWith(".json") || m.endsWith(".py") || m.endsWith(".css") ||
      m.endsWith(".html") || m.endsWith(".yml") || m.endsWith(".yaml")) {
    summaryPaths.add(m);
  }
}

console.log("=== Auto-compact summary stats ===");
console.log("Summary length:", summary.length, "chars");
console.log("File paths mentioned in summary:", summaryPaths.size);
if (summaryPaths.size > 0) {
  console.log("Sample paths:");
  [...summaryPaths].slice(0, 8).forEach(p => console.log("  " + p));
}

// Now walk assistant turns after L2942 until next user turn, collect Read tool_use file paths
const readPaths = [];
let nextUserLine = -1;
for (let i = 2942; i < Math.min(lines.length, 5000); i++) {
  const line = lines[i];
  if (!line) continue;
  try {
    const obj = JSON.parse(line);
    if (obj.type === "user") {
      const c = obj.message && obj.message.content;
      const hasToolResult = Array.isArray(c) && c.some(b => b.type === "tool_result");
      if (!hasToolResult) { nextUserLine = i; break; }
    }
    if (obj.type === "assistant") {
      const c = obj.message && obj.message.content;
      if (Array.isArray(c)) {
        for (const b of c) {
          if (b.type === "tool_use" && b.name === "Read") {
            const fp = b.input && b.input.file_path;
            if (fp) readPaths.push(fp);
          }
        }
      }
    }
  } catch(e){}
}

console.log("\n=== Reads after compact (until next user turn at line " + nextUserLine + ") ===");
console.log("Total Read calls:", readPaths.length);

// How many Read calls target files that were already mentioned in the summary?
let inSummary = 0, uniqueInSummary = new Set();
for (const rp of readPaths) {
  // Match by suffix (summary may use relative or absolute paths)
  for (const sp of summaryPaths) {
    const spBase = sp.split("/").pop();
    const rpBase = rp.split("/").pop();
    if (spBase && rpBase && spBase === rpBase) {
      inSummary++;
      uniqueInSummary.add(rp);
      break;
    }
  }
}
console.log("Reads whose filename appears in summary:", inSummary);
console.log("Unique such files:", uniqueInSummary.size);
console.log("Sample overlapping reads:");
[...uniqueInSummary].slice(0, 6).forEach(p => console.log("  " + p));

// Also: which Read targets appear 2+ times (re-read)
const readCount = {};
for (const rp of readPaths) readCount[rp] = (readCount[rp]||0)+1;
const multi = Object.entries(readCount).filter(([_,n]) => n >= 2).sort((a,b)=>b[1]-a[1]);
console.log("\n=== Re-reads within the same turn ===");
console.log("Files read 2+ times:", multi.length);
multi.slice(0, 5).forEach(([p, n]) => console.log(`  ${n}× ${p}`));
