const compactLines = [];
let totalRows = 0;
let totalAssistantRows = 0;
let totalToolUseBlocks = 0;
let totalToolResultBytes = 0;
const rowsBetween = [];
let lastCompactLine = 0;

for (let i = 0; i < lines.length; i++) {
  const line = lines[i];
  if (!line) continue;
  try {
    const obj = JSON.parse(line);
    if (obj.version && !version) version = obj.version;
    if (obj.timestamp) {
      if (!firstTs) firstTs = obj.timestamp;
      lastTs = obj.timestamp;
    }
    totalRows++;
    if (obj.type === "assistant") {
      totalAssistantRows++;
      const m = obj.message && obj.message.model;
      if (m) assistantModels.add(m);
      const c = obj.message && obj.message.content;
      if (Array.isArray(c)) {
        for (const b of c) if (b.type === "tool_use") totalToolUseBlocks++;
      }
    }
    if (obj.type === "user") {
      const c = obj.message && obj.message.content;
      if (Array.isArray(c)) {
        for (const b of c) if (b.type === "tool_result") {
          const t = typeof b.content === "string" ? b.content : JSON.stringify(b.content||"");
          totalToolResultBytes += t.length;
        }
      }
      if (typeof c === "string" && c.startsWith("This session is being continued")) {
        compactLines.push({ line: i+1, ts: obj.timestamp, summaryBytes: c.length, isCompactSummary: obj.isCompactSummary });
        if (lastCompactLine > 0) rowsBetween.push(i+1 - lastCompactLine);
        lastCompactLine = i+1;
      }
    }
  } catch(e){}
}

console.log("=== Session metadata ===");
console.log("Version:", version);
console.log("Models:", [...assistantModels].join(", "));
console.log("Time range:", firstTs, "→", lastTs);
console.log("Total JSONL rows:", totalRows);
console.log("Assistant rows:", totalAssistantRows);
console.log("Tool use blocks:", totalToolUseBlocks);
console.log("Total tool_result bytes:", totalToolResultBytes.toLocaleString(), "(~" + Math.round(totalToolResultBytes/4).toLocaleString() + " tokens)");

console.log("\n=== Compacts ===");
console.log("Count:", compactLines.length);
console.log("Rows between compacts:", rowsBetween);
console.log("Summary bytes:", compactLines.map(c => c.summaryBytes));

// Time gaps between compacts
console.log("\n=== Time gaps ===");
for (let i = 1; i < compactLines.length; i++) {
  const t1 = new Date(compactLines[i-1].ts);
  const t2 = new Date(compactLines[i].ts);
  const mins = Math.round((t2-t1)/60000);
  console.log(`#${i}→#${i+1}: ${mins} min`);
}
