const fs = require("fs");
const path = require("path");
const home = require("os").homedir();

// Find sessions with manual compact markers (+) in compact.txt
const base = home + "/.claude/cc-token-saver-data";
const manualCompactSessions = [];

function walk(dir) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (!entry.isDirectory()) continue;
    const full = path.join(dir, entry.name);
    const compactPath = path.join(full, "compact.txt");
    if (fs.existsSync(compactPath)) {
      const content = fs.readFileSync(compactPath, "utf8");
      // Manual compact = single +, not ++ (auto)
      // ALERT_LINE_RE in build-report.js: look for `]+` but NOT `]++`
      const matches = content.match(/\]\+(?!\+)/g) || [];
      if (matches.length > 0) {
        manualCompactSessions.push({
          sid: entry.name,
          proj: path.basename(dir),
          count: matches.length,
          path: compactPath
        });
      }
    } else if (entry.name !== "subagents" && entry.name !== "tool-results") {
      walk(full);
    }
  }
}

for (const proj of fs.readdirSync(base)) {
  const pdir = path.join(base, proj);
  if (!fs.statSync(pdir).isDirectory()) continue;
  try { walk(pdir); } catch(e){}
