const results = [];
function scanProject(projDir) {
  for (const entry of fs.readdirSync(projDir)) {
    const full = path.join(projDir, entry);
    try {
      const st = fs.statSync(full);
      if (st.isFile() && entry.endsWith(".jsonl")) {
        const lines = fs.readFileSync(full, "utf8").split("\n");
        let autoCount = 0, manualCount = 0;
        for (const line of lines) {
          if (!line) continue;
          if (!line.includes("compact_boundary")) continue;
          try {
            const o = JSON.parse(line);
            if (o.type === "system" && o.subtype === "compact_boundary") {
              const trig = o.compactMetadata && o.compactMetadata.trigger;
              if (trig === "manual") manualCount++;
              else if (trig === "auto") autoCount++;
              else manualCount++;  // default = manual
            }
          } catch(e){}
        }
        if (manualCount > 0) {
          results.push({ sid: entry.slice(0,8), proj: path.basename(projDir), manual: manualCount, auto: autoCount, file: full });
        }
      }
    } catch(e){}
  }
}

for (const proj of fs.readdirSync(home + "/.claude/projects")) {
