if (!csvPath || !fs.existsSync(csvPath)) return null;
const content = fs.readFileSync(csvPath, 'utf8').trim();
const lines = content.split('\n');
if (lines.length < 2) return null;
let ctxSize = null;
let model = '';
const totals = { input: 0, cc5m: 0, cc1h: 0, cr: 0, out: 0, cost: 0, callCount: 0 };
let firstTs = null, lastTs = null;
const markerRe = /^compact:(?:auto|manual):(\d+)/;
for (let i = 1; i < lines.length; i++) {
  const cols = lines[i].split(',');
  if (cols.length < 11) continue;
  const evt = cols[11] || '';
  if (ctxSize === null) {
    const m = evt.match(markerRe);
    if (m) ctxSize = Number(m[1]);
  }
  if (cols[1]) model = cols[1];
  const ts = Number(cols[0]);
  if (ts) {
    if (firstTs === null || ts < firstTs) firstTs = ts;
    if (lastTs === null || ts > lastTs) lastTs = ts;
  }
  const cost = Number(cols[8]) || 0;
  const input = Number(cols[2]) || 0;
  if (cost > 0 || input > 0) {
    totals.input += input;
    totals.cc5m += Number(cols[4]) || 0;
    totals.cc1h += Number(cols[5]) || 0;
    totals.cr += Number(cols[6]) || 0;

