      totals.input += input;
      totals.cc5m += Number(cols[4]) || 0;
      totals.cc1h += Number(cols[5]) || 0;
      totals.cr += Number(cols[6]) || 0;
      totals.out += Number(cols[7]) || 0;
      totals.cost += cost;
      totals.callCount++;
    }
  }
  return { ctxSize, model, totals, firstTs, lastTs };
}

