// Read a subagent's timeline.csv and return {ctxSize, model, totals}.
// Used for acompact aggregation BEFORE main allTimelines build.
//
// CC source investigation (services/compact/compact.ts:1188) reveals that each
// acompact subagent is a fork with `maxTurns: 1` that does EXACTLY ONE new
// summary LLM call. All other assistant rows in the acompact timeline.csv are
// parent-session messages REPLAYED into the sidechain file at fork start — they
// carry the original usage fields and were ALREADY billed by the parent. Summing
// every row double-counts parent cost.
//
// Correct behavior: aggregate ONLY the last assistant row with actual cost,
// which represents the single new summary call. Everything else is replay.
function readAcompactAggregate(proj, parentSessionId, agentDirName) {
  const csvPath = getSubagentTimelinePath(proj, parentSessionId, agentDirName);
  if (!csvPath || !fs.existsSync(csvPath)) return null;
  const content = fs.readFileSync(csvPath, 'utf8').trim();
  const lines = content.split('\n');
  if (lines.length < 2) return null;
  let ctxSize = null;
  let model = '';
  let firstTs = null, lastTs = null;
  const markerRe = /^compact:(?:auto|manual):(\d+)/;
  // Track the LAST row with real cost — that's the summary call.
  let lastCostRow = null;
  for (let i = 1; i < lines.length; i++) {
    const cols = lines[i].split(',');
    if (cols.length < 11) continue;
    const evt = cols[11] || '';
    if (ctxSize === null) {
      const m = evt.match(markerRe);
      if (m) ctxSize = Number(m[1]);
    }
    if (cols[1]) model = cols[1];
    const ts = Number(cols[0]);
    if (ts) {
      if (firstTs === null || ts < firstTs) firstTs = ts;
      if (lastTs === null || ts > lastTs) lastTs = ts;
    }
    const cost = Number(cols[8]) || 0;
    const input = Number(cols[2]) || 0;
    if (cost > 0 || input > 0) {
      // Overwrite — we only want the final row (summary call).
      lastCostRow = {
        input,
        cc5m: Number(cols[4]) || 0,
        cc1h: Number(cols[5]) || 0,
        cr: Number(cols[6]) || 0,
        out: Number(cols[7]) || 0,
        cost
      };
    }
  }
  if (!lastCostRow) return { ctxSize, model, totals: null, firstTs, lastTs };
  const totals = {
    input: lastCostRow.input,
    cc5m: lastCostRow.cc5m,
    cc1h: lastCostRow.cc1h,
    cr: lastCostRow.cr,
    out: lastCostRow.out,
    cost: lastCostRow.cost,
    callCount: 1  // exactly 1 new summary call per CC auto-compact contract
  };
  return { ctxSize, model, totals, firstTs, lastTs };
}

