const fs = require("fs");
const path = require("path");
const home = require("os").homedir();

// For EACH subagent type, pick a few samples and measure overlap with parent
const samples = { regular: [], acompact: [], aside_question: [] };

function scanProject(projDir) {
  for (const entry of fs.readdirSync(projDir, { withFileTypes: true })) {
    if (!entry.isDirectory()) continue;
    const sid = entry.name;
    const parentJsonl = path.join(projDir, sid + ".jsonl");
    if (!fs.existsSync(parentJsonl)) continue;
    const subDir = path.join(projDir, sid, "subagents");
    if (!fs.existsSync(subDir)) continue;
    const files = fs.readdirSync(subDir).filter(f => f.endsWith(".jsonl"));
    for (const f of files) {
      const full = path.join(subDir, f);
      let type = "regular";
      if (f.startsWith("agent-acompact-")) type = "acompact";
      else if (f.startsWith("agent-aside_question-")) type = "aside_question";
      if (samples[type].length < 3) {
        samples[type].push({ parent: parentJsonl, sub: full });
      }
    }
  }
}
for (const proj of fs.readdirSync(home + "/.claude/projects")) {
  const pd = home + "/.claude/projects/" + proj;
  try { if (fs.statSync(pd).isDirectory()) scanProject(pd); } catch(e){}
}

function getReqIds(file) {
  const ids = new Set();
  const lines = fs.readFileSync(file, "utf8").split("\n");
  for (const line of lines) {
    if (!line) continue;
    try {
      const o = JSON.parse(line);
      if (o.type !== "assistant") continue;
      const id = o.requestId || (o.message && o.message.id);
      if (id) ids.add(id);
    } catch(e){}
  }
  return ids;
}

for (const [type, pairs] of Object.entries(samples)) {
  console.log(`\n=== ${type} ===`);
  for (const p of pairs) {
    const subIds = getReqIds(p.sub);
    const parentIds = getReqIds(p.parent);
    let overlap = 0;
    for (const id of subIds) if (parentIds.has(id)) overlap++;
    const pct = subIds.size > 0 ? (100 * overlap / subIds.size).toFixed(0) : "?";
    console.log(`  ${path.basename(p.sub).slice(0, 35)}  sub=${subIds.size} overlap=${overlap} (${pct}%)`);
