const fs = require("fs");
const path = require("path");
const home = require("os").homedir();

// Look for ANY regular Task subagent with high overlap (= potentially worktree fork)
const highOverlapSamples = [];
function scanProject(projDir) {
  for (const entry of fs.readdirSync(projDir, { withFileTypes: true })) {
    if (!entry.isDirectory()) continue;
    const sid = entry.name;
    const parentJsonl = path.join(projDir, sid + ".jsonl");
    if (!fs.existsSync(parentJsonl)) continue;
    const subDir = path.join(projDir, sid, "subagents");
    if (!fs.existsSync(subDir)) continue;
    const files = fs.readdirSync(subDir).filter(f => f.endsWith(".jsonl"));

    // Get parent requestIds once
    let parentIds = null;
    for (const f of files) {
      if (f.startsWith("agent-acompact-") || f.startsWith("agent-aside_question-")) continue;
      if (!/^agent-a[0-9a-f]+\.jsonl$/.test(f)) continue;
      // It's a "regular" agent. Check overlap.
      if (!parentIds) {
        parentIds = new Set();
        try {
          const pLines = fs.readFileSync(parentJsonl, "utf8").split("\n");
          for (const line of pLines) {
            if (!line) continue;
            try {
              const o = JSON.parse(line);
              if (o.type !== "assistant") continue;
              const id = o.requestId || (o.message && o.message.id);
              if (id) parentIds.add(id);
            } catch(e){}
          }
        } catch(e){ parentIds = new Set(); }
      }

      const subIds = new Set();
      try {
        const sLines = fs.readFileSync(path.join(subDir, f), "utf8").split("\n");
        for (const line of sLines) {
          if (!line) continue;
          try {
            const o = JSON.parse(line);
            if (o.type !== "assistant") continue;
            const id = o.requestId || (o.message && o.message.id);
            if (id) subIds.add(id);
          } catch(e){}
        }
      } catch(e){}

      if (subIds.size < 3) continue;
      let overlap = 0;
      for (const id of subIds) if (parentIds.has(id)) overlap++;
      const pct = (100 * overlap / subIds.size);
      if (pct >= 50) {
        highOverlapSamples.push({ sid: sid.slice(0,8), file: f.slice(0,35), size: subIds.size, overlap, pct: pct.toFixed(0) });
      }
    }
  }
}

for (const proj of fs.readdirSync(home + "/.claude/projects")) {
  const pd = home + "/.claude/projects/" + proj;
  try { if (fs.statSync(pd).isDirectory()) scanProject(pd); } catch(e){}
}

console.log("Regular agent-a{hex} subagents with >=50% parent overlap:");
console.log("(these could be worktree forks with parent context inherited)\n");
if (highOverlapSamples.length === 0) {
  console.log("  NONE — all regular subagents are truly independent.");
} else {
  highOverlapSamples.forEach(s => console.log(`  ${s.sid}/${s.file}  sub=${s.size} overlap=${s.overlap} (${s.pct}%)`));
}
console.log("\nTotal suspicious regular subagents:", highOverlapSamples.length, "/ 1623");
