const fs = require("fs");
const path = require("path");
const home = require("os").homedir();

// Calculate expected saving from acompact dedup
let acompactTotalRows = 0, acompactTotalCost = 0;
let acompactFileCount = 0;
let regularTotalCost = 0, regularFileCount = 0;
let asideTotalCost = 0, asideFileCount = 0;

const base = home + "/.claude/cc-token-saver-data";
function scan(dir) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (!entry.isDirectory()) continue;
    const subDir = path.join(dir, entry.name, "subagents");
    if (!fs.existsSync(subDir)) continue;
    for (const sub of fs.readdirSync(subDir, { withFileTypes: true })) {
      if (!sub.isDirectory()) continue;
      const tl = path.join(subDir, sub.name, "timeline.csv");
      if (!fs.existsSync(tl)) continue;
      const lines = fs.readFileSync(tl, "utf8").split("\n");
      let cost = 0, rowCount = 0;
      for (let i = 1; i < lines.length; i++) {
        const cols = lines[i].split(",");
        if (cols.length < 9) continue;
        const c = Number(cols[8]) || 0;
        if (c > 0 || Number(cols[2]) > 0) {
          cost += c;
          rowCount++;
        }
      }
      if (sub.name.startsWith("acompact-")) {
        acompactTotalRows += rowCount;
        acompactTotalCost += cost;
        acompactFileCount++;
      } else if (sub.name.startsWith("aside_question-")) {
        asideTotalCost += cost;
        asideFileCount++;
      } else if (/^a[0-9a-f]+$/.test(sub.name)) {
        regularTotalCost += cost;
        regularFileCount++;
      }
    }
  }
}
for (const proj of fs.readdirSync(base)) {
  const pd = path.join(base, proj);
  if (!fs.statSync(pd).isDirectory()) continue;
  try { scan(pd); } catch(e){}
}

console.log("=== Raw subagent costs from timeline.csv ===");
console.log(`Acompact (${acompactFileCount} files, ${acompactTotalRows} rows): $${acompactTotalCost.toFixed(2)}`);
console.log(`Aside_question (${asideFileCount} files): $${asideTotalCost.toFixed(2)}`);
console.log(`Regular (${regularFileCount} files): $${regularTotalCost.toFixed(2)}`);
console.log(`\nTotal subagent raw: $${(acompactTotalCost + asideTotalCost + regularTotalCost).toFixed(2)}`);

// Estimate post-dedup
// Acompact: only ~1 new call per file, avg $0.24 per my earlier measurement
const acompactAfter = acompactFileCount * 0.24;
const asideAfter = asideFileCount * 0.30;  // similar
const regularAfter = regularTotalCost;  // unchanged
console.log(`\n=== Expected after dedup ===`);
console.log(`Acompact: $${acompactAfter.toFixed(2)} (${acompactFileCount} × $0.24)`);
console.log(`Aside_question: $${asideAfter.toFixed(2)} (${asideFileCount} × $0.30)`);
console.log(`Regular: $${regularAfter.toFixed(2)}`);

const expectedDrop = (acompactTotalCost - acompactAfter) + (asideTotalCost - asideAfter);
console.log(`\nExpected TOTAL drop: $${expectedDrop.toFixed(2)}`);
console.log(`Observed drop: $9525 → $6818 = $2707`);
console.log(`Unexplained: $${(2707 - expectedDrop).toFixed(2)}`);
