    wCost += total; wDays.push(d.date + ':$' + total);
    if (wDays.length === 7) {
      weeks.push('Week' + wn + ': total=$' + round2(wCost) + ' [' + wDays.join(', ') + ']');
      wCost = 0; wDays = []; wn++;
