var ctxCostGranularity = 'call'; // 'call' or 'turn'
function renderContextCostCharts() {
  var ccs = REPORT_DATA.contextCostScatter;
  if (!ccs) return;
  var data, yLabel, titleText, footnote;
  if (ctxCostGranularity === 'turn' && ccs.perUserTurn && ccs.perUserTurn.points && ccs.perUserTurn.points.length > 0) {
    data = ccs.perUserTurn;
    yLabel = 'Cost per user turn ($)';
    titleText = '\uD83D\uDCB8 Context Size vs High-Cost User Turns ($' + (data.costFloor || 4).toFixed(0) + '+)';
    footnote = '* Each dot = one user prompt turn with aggregated cost \u2265 $' + (data.costFloor || 4).toFixed(0) + ' (sum of all API calls triggered). X = context size at turn start. Hover for details. Trend = linear regression.';
  } else {
    data = ccs.perAssistant;
    yLabel = 'Cost per API call ($)';
    titleText = '\uD83D\uDCB8 Context Size vs High-Cost API Calls ($' + (data.costFloor || 1).toFixed(0) + '+)';
    footnote = '* Only API calls costing \u2265 $' + (data.costFloor || 1).toFixed(0) + ' are plotted. Cheap calls (< $1) don\'t follow this linear relationship \u2014 this chart shows the "expensive tail" where context size drives cost. Hover for details. Trend = linear regression.';
  }
  if (!data || !data.points || data.points.length === 0) {
    var cont = document.getElementById('ctxCostAsstContainer');
    if (cont) cont.style.display = 'none';
    return;
  }
  // Update title span (only the text part, preserving the toggle buttons)
  var titleSpan = document.querySelector('.ctx-cost-section-title');
  if (titleSpan) titleSpan.textContent = titleText;
  // Update footnote
  var fn = document.getElementById('ctxCostFootnote');
  if (fn) fn.textContent = footnote;
  renderContextCostChart('ctxCostAsstChart', 'ctxCostAsstContainer', data, yLabel, data.costFloor || 1.0);
}

// Toggle handler for Per API Call / Per User Turn
(function setupCtxCostGranularityToggle() {
  var btnContainer = document.getElementById('ctxCostGranularity');
  if (!btnContainer) return;
  var btns = btnContainer.querySelectorAll('.ctx-cost-btn');
  btns.forEach(function(b) {
    b.addEventListener('click', function() {
      var g = b.getAttribute('data-granularity');
      if (g === ctxCostGranularity) return;
      ctxCostGranularity = g;
      // Update button styles
      btns.forEach(function(x) {
        var active = x.getAttribute('data-granularity') === g;
        x.classList.toggle('active', active);
        x.style.background = active ? 'var(--accent)' : 'var(--bg-tertiary)';
        x.style.color = active ? '#fff' : 'var(--text-secondary)';
      });
      renderContextCostCharts();
    });
  });
})();

