const fs = require("fs");
const home = require("os").homedir();

// Find session 81d81d93
const projects = fs.readdirSync(home + "/.claude/projects");
let jsonl = null, proj = null;
for (const p of projects) {
  const d = home + "/.claude/projects/" + p;
  try {
    const files = fs.readdirSync(d).filter(f => f.startsWith("81d81d93") && f.endsWith(".jsonl"));
    if (files.length > 0) { jsonl = d + "/" + files[0]; proj = p; break; }
  } catch(e){}
}
if (!jsonl) { console.log("not found"); process.exit(0); }
console.log("Session:", jsonl.split("/").pop().slice(0,8));
console.log("Project:", proj);

// Find the "서비스 띄워" user turn line
const lines = fs.readFileSync(jsonl, "utf8").split("\n");
let turnUserLine = -1, turnUserTs = null;
for (let i = 0; i < lines.length; i++) {
  if (!lines[i]) continue;
  try {
    const o = JSON.parse(lines[i]);
    if (o.type !== "user") continue;
    const c = o.message && o.message.content;
    const text = typeof c === "string" ? c : (Array.isArray(c) ? c.map(b => b.text||"").join("") : "");
    if (text === "서비스 띄워" || text.startsWith("서비스 띄워")) {
      turnUserLine = i + 1;
      turnUserTs = o.timestamp;
      console.log("Found user turn at L" + turnUserLine + " ts=" + o.timestamp);
      break;
    }
  } catch(e){}
}
if (turnUserLine < 0) { console.log("user turn not found"); process.exit(0); }

// Find the NEXT user message to determine the turn boundary
let nextUserLine = lines.length, nextUserTs = null;
for (let i = turnUserLine; i < lines.length; i++) {
  if (!lines[i]) continue;
  try {
    const o = JSON.parse(lines[i]);
    if (o.type === "user") {
      const c = o.message && o.message.content;
      const text = typeof c === "string" ? c : "";
      // Skip tool_result-style user messages
      if (Array.isArray(c) && c.some(b => b.type === "tool_result")) continue;
      if (text && !text.startsWith("This session")) {
        nextUserLine = i + 1;
        nextUserTs = o.timestamp;
        break;
      }
    }
  } catch(e){}
}
console.log("Next user turn at L" + nextUserLine + " ts=" + nextUserTs);
const wallSec = (new Date(nextUserTs) - new Date(turnUserTs)) / 1000;
console.log("Wall duration: " + Math.round(wallSec/60) + " minutes (" + (wallSec/3600).toFixed(2) + " hours)");

// Sum all assistant call cost between turnUserLine and nextUserLine
let totalCost = 0, callCount = 0, totalTokens = { input: 0, cr: 0, cc: 0, out: 0 };
for (let i = turnUserLine; i < nextUserLine; i++) {
  if (!lines[i]) continue;
  try {
    const o = JSON.parse(lines[i]);
    if (o.type !== "assistant") continue;
    const u = o.message && o.message.usage;
    if (!u) continue;
    callCount++;
