  const boundaries = [];
  for (let i = 0; i < lines.length; i++) {
    if (!lines[i] || !lines[i].includes("compact_boundary")) continue;
    try {
      const o = JSON.parse(lines[i]);
      if (o.type === "system" && o.subtype === "compact_boundary") {
