  }

  // Per-user-turn: group non-merged rows by enclosing user line, then emit
  // one point per turn with aggregated cost >= USER_TURN_COST_FLOOR.
  // Context x-value = the FIRST row's context (starting context of the turn).
  if (isSubagent || sortedUsers.length === 0) continue;
  const turnGroups = new Map();
  for (const row of rows) {
    if (row.cost <= 0 || row.input <= 0) continue;
    if (row.mergedFromAcompact) continue;
    const rline = row.line || 0;
    if (rline <= 0) continue;
    const parent = findEnclosingUser(rline);
    if (!parent) continue;
    let g = turnGroups.get(parent.lineNum);
    if (!g) {
      g = {
        alert: parent, firstCtx: null, cost: 0, callCount: 0,
        input: 0, out: 0, cc: 0, cr: 0, evts: new Set(), rl: ''
      };
      turnGroups.set(parent.lineNum, g);
    }
    const ctx = (row.input || 0) + (row.cc || 0) + (row.cr || 0);
    if (g.firstCtx === null) g.firstCtx = ctx;
    g.cost += row.cost;
    g.callCount++;
    g.input += row.input || 0;
    g.out += row.out || 0;
    g.cc += (row.cc5m || 0) + (row.cc1h || 0);
    g.cr += row.cr || 0;
    for (const e of (row.evt || '').split('|')) if (e) g.evts.add(e);
    if (row.rl && !g.rl) g.rl = row.rl;
  }
  for (const g of turnGroups.values()) {
    if (g.cost < USER_TURN_COST_FLOOR) continue;
    if (g.firstCtx === null || g.firstCtx <= 0) continue;
    // Rebuild badge from aggregated cost against turn thresholds.
    const aggEvts = new Set(g.evts);
    aggEvts.delete('cost_warn');
    aggEvts.delete('cost_danger');
    if (g.cost >= 10.0) aggEvts.add('cost_danger');
    else if (g.cost >= USER_TURN_COST_FLOOR) aggEvts.add('cost_warn');
    userTurnPoints.push({
      x: g.firstCtx,
      y: Math.round(g.cost * 10000) / 10000,
      badge: evtRlToBadge(Array.from(aggEvts).join('|'), g.rl),
      time: g.alert.time,
      sid: shortSid,
      text: g.alert.text || '',
      input: g.input,
      out: g.out,
      cc: g.cc,
      cr: g.cr,
      callCount: g.callCount
    });
  }
}

// Simple least-squares linear regression over a point list.
// Returns { slope, intercept, x0, x1 } for frontend to plot as a 2-point line.
function linearTrend(points) {
  if (!points || points.length < 2) return null;
  let n = 0, sx = 0, sy = 0, sxx = 0, sxy = 0;
  let x0 = Infinity, x1 = -Infinity;
  for (const p of points) {
    n++; sx += p.x; sy += p.y; sxx += p.x * p.x; sxy += p.x * p.y;
    if (p.x < x0) x0 = p.x;
    if (p.x > x1) x1 = p.x;
  }
  const denom = n * sxx - sx * sx;
  if (denom === 0) return null;
  const slope = (n * sxy - sx * sy) / denom;
  const intercept = (sy - slope * sx) / n;
  return { slope, intercept, x0, x1 };
}

