    process.exit(1);
  }
  const endIdx = endRaw + marker_end.length;
  const output = template.slice(0, startIdx) +
    marker_start + '\nconst REPORT_DATA = ' + JSON.stringify(reportData, null, 0) + ';\n' + marker_end +
    template.slice(endIdx);
