if ((!dataPath && !importDataPath) || !outputPath) {
  console.error('Usage: node build-report.js --data <results.json> --output <report.html>');
  process.exit(1);
}

// ── i18n injection helper ──────────────────────────────────────
function injectI18N(html) {
