const fs = require("fs");
const path = require("path");
const home = require("os").homedir();

// Find all unique models across all sessions + first/last seen date
const modelDates = {};
function scan(dir) {
  for (const f of fs.readdirSync(dir)) {
    const full = path.join(dir, f);
    try {
      const st = fs.statSync(full);
      if (st.isFile() && f.endsWith(".jsonl")) {
        const lines = fs.readFileSync(full, "utf8").split("\n");
        for (const line of lines) {
          if (!line) continue;
          try {
            const o = JSON.parse(line);
            const m = o.message && o.message.model;
            if (!m || m === "<synthetic>") continue;
            if (!modelDates[m]) modelDates[m] = { first: o.timestamp, last: o.timestamp, count: 0 };
            if (o.timestamp < modelDates[m].first) modelDates[m].first = o.timestamp;
            if (o.timestamp > modelDates[m].last) modelDates[m].last = o.timestamp;
            modelDates[m].count++;
          } catch(e){}
        }
      }
    } catch(e){}
  }
}
for (const proj of fs.readdirSync(home + "/.claude/projects")) {
  const pd = home + "/.claude/projects/" + proj;
  try { if (fs.statSync(pd).isDirectory()) scan(pd); } catch(e){}
}

console.log("=== Model usage across all sessions ===");
for (const [m, d] of Object.entries(modelDates).sort((a,b)=>b[1].count-a[1].count)) {
  console.log(`  ${m.padEnd(35)} count=${d.count.toString().padStart(7)}  first=${d.first.slice(0,10)}  last=${d.last.slice(0,10)}`);
}
