        for (const line of lines) {
          if (!line || !line.includes("compact_boundary")) continue;
          try {
            const o = JSON.parse(line);
            if (o.type !== "system" || o.subtype !== "compact_boundary") continue;
            const d = o.timestamp ? o.timestamp.slice(0,10) : "?";
            if (!dailyCompacts[d]) dailyCompacts[d] = { auto: 0, manual: 0 };
            const trig = o.compactMetadata && o.compactMetadata.trigger;
            if (trig === "manual") dailyCompacts[d].manual++;
            else dailyCompacts[d].auto++;
          } catch(e){}
        }
      }
    } catch(e){}
  }
}
for (const proj of fs.readdirSync(home + "/.claude/projects")) {
