          const u = getUsage(lines[j]);
          if (u && u.total > 0) { before = u; break; }
        }
        for (let j = i+1; j < Math.min(lines.length, i+200); j++) {
          const u = getUsage(lines[j]);
          if (u && u.total > 0) { after = u; break; }
        }
        const summaryCall = acompactByCtx.get(ctxSize);
        const item = {
          sid: sid.slice(0,8), ctxSize,
          beforeCtx: before?.total, beforeCr: before?.cr,
          afterCtx: after?.total, afterCc: after?.cc,
          summaryCall, ts: o.timestamp, trigger: o.compactMetadata?.trigger
        };
        if (!before || !after) { item.failed = true; unmatchedData.push(item); }
        else if (summaryCall) matchedData.push(item);
        else unmatchedData.push(item);
      } catch(e){}
    }
  }
}

