  const predicted = (s.cr * 0.5 + s.out * 25 + s.input * 5 + (s.cc + s.cc5m) * 7.5) / 1e6;
  const err = Math.abs(predicted - s.cost);
  errors.push({ predicted, actual: s.cost, err, pct: err/s.cost*100 });
  totalErr += err;
});
